				try { unlinkSync(row.path); } catch { /* 删不掉就算了 */ }
			}
		} catch { /* 目录读不到就算了 */ }
		return name;
	} catch (error) {
		this.log('warn', `[fish-soul] 把图库的动图放进 _stickers 失败：${String(error instanceof Error ? error.message : error)}`);
		return '';
	}
}

